            name = parts[-1]
            if addr > 0:
                funcs.append((addr, size, name))
        except (ValueError, IndexError):
            pass

funcs.sort()

for target in targets:
    best = None
    for addr, size, name in funcs:
        if addr <= target:
            best = (addr, size, name)
        else:
            break
    if best:
        offset = target - best[0]
        print(f"0x{target:x}: {best[2]}+0x{offset:x} (base 0x{best[0]:x}, size {best[1]})")
    else:
        print(f"0x{target:x}: ???")
EOF

