for line in result.stdout.splitlines():
    parts = line.split()
    if len(parts) < 8:
        continue
    if 'FUNC' not in parts:
        continue
    # Format: Num: Value Size Type Bind Vis Ndx Name
    # e.g.:  18: 00000000000c2490     8 FUNC    LOCAL  HIDDEN    14 __emutls_unregister_key
    try:
        # Find the Value field (hex number after the colon)
        for i, p in enumerate(parts):
            if p.endswith(':'):
                val_str = parts[i+1]
                size_str = parts[i+2]
                name_str = parts[-1]
                addr = int(val_str, 16)
                size = int(size_str)
                if addr > 0:
                    funcs.append((addr, size, name_str))
                break
    except (ValueError, IndexError):
        pass

funcs.sort()
print(f"Total FUNC symbols: {len(funcs)}")
print(f"Max addr: 0x{funcs[-1][0]:x}" if funcs else "No funcs")

# Find closest
for target in targets:
    best = None
    for addr, size, name in funcs:
        if addr <= target:
            best = (addr, size, name)
        else:
            break
    if best:
        offset = target - best[0]
        print(f"0x{target:x}: {best[2]}+0x{offset:x} (base 0x{best[0]:x}, size {best[1]})")
    else:
        print(f"0x{target:x}: no symbol found (first func at 0x{funcs[0][0]:x})")
EOF

